	@Test 
	public void testDummy() throws NoSuchAlgorithmException, ParseException {
		Object value = new JSONParser().parse(na);
		String hash = JDigest.digest(value, new StringBuilder());
		assertEquals("digest error", "1f03f837d2d878651581505168631121", hash);
	}

	@SuppressWarnings("rawtypes")
	@Test public void testOutput() throws ParseException, NoSuchAlgorithmException, IOException {
		Map value = (Map) new JSONParser().parse(na);
		StringBuilder sb = new StringBuilder();
		JDigest.digest(value,sb);
		assertEquals("LENGTH", md5.length(), sb.length());
		assertEquals("MD5 input wrong", md5, sb.toString());
		FileOutputStream klad = new FileOutputStream("target/klad.txt");
		klad.write(sb.toString().getBytes(StandardCharsets.UTF_8));
		klad.close();
		
	}
	
	@Test public void testMD5() throws NoSuchAlgorithmException { 
		String result = md5(md5);
		assertEquals("md5 wrong", "1f03f837d2d878651581505168631121", result);

	}

	private String md5(String md52) throws NoSuchAlgorithmException {
	    MessageDigest md5 = MessageDigest.getInstance("MD5");
	    md5.update(md52.getBytes(StandardCharsets.UTF_8));
	    byte[] bytes = md5.digest();
	    return javax.xml.bind.DatatypeConverter.printHexBinary(bytes).toLowerCase();
	}
